# Check connectivity of 6s using flood fill
from collections import deque

def find_connected_components(grid, start_color):
    visited = set()
    component_count = 0

    # Get all cells of this color
    cells_by_color = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == start_color:
                cells_by_color[start_color].append((r,c))

    all_cells = cells_by_color[start_color]

    for i, (sr, sc) in enumerate(all_cells):
        if (sr, sc) in visited:
            continue

        # BFS from this cell
        component = []
        queue = deque([(sr, sc)])
        visited.add((sr, sc))

        while queue:
            r, c = queue.popleft()
            component.append((r, c))

            # Check 4-connected neighbors
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] == start_color and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        component_count += 1

    return component_count, visited

component_count, _ = find_connected_components(grid, 6)
print(f"Number of connected components of color 6: {component_count}")

