from copy import deepcopy

def fill_bounding_box(grid, color):
    # Get all cells of this color
    cells = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                cells.append((r, c))

    if not cells:
        return grid

    min_r, max_r = min(c[0] for c in cells), max(c[0] for c in cells)
    min_c, max_c = min(c[1] for c in cells), max(c[1] for c in cells)

    new_grid = deepcopy(grid)

    # Fill the entire bounding box with the color
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            new_grid[r][c] = color

    return new_grid

