def analyze_color(color):
    cells = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
    if not cells:
        return None

    min_r, max_r = min(c[0] for c in cells), max(c[0] for c in cells)
    min_c, max_c = min(c[1] for c in cells), max(c[1] for c in cells)
    bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)

    return {
        'color': color,
        'count': len(cells),
        'bbox_area': bbox_area,
        'min_r': min_r, 'max_r': max_r,
        'min_c': min_c, 'max_c': max_c
    }

