from collections import deque

def find_largest_component(grid, color):
    """Return only the largest connected component of a given color."""
    visited = set()
    components = []

    # Get all cells of this color
    cells = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]

    for start_r, start_c in cells:
        if (start_r, start_c) not in visited:
            comp_size = 0
            queue = deque([(start_r, start_c)])
            visited.add((start_r, start_c))

            while queue:
                r, c = queue.popleft()
                comp_size += 1

                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            components.append(comp_size)

    if not components:
        return set(), set()

    max_comp = max(components)

    # Return coordinates of the largest component(s)
    largest_coords = set()
    start_found = False

    for start_r, start_c in cells:
        if (start_r, start_c) not in visited and not start_found:
            queue = deque([(start_r, start_c)])
            visited.add((start_r, start_c))
            current_coords = {(start_r, start_c)}

            while queue:
                r, c = queue.popleft()
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                            current_coords.add((nr, nc))

            if len(current_coords) == max_comp:
                largest_coords.update(current_coords)

        if (len(largest_coords) > 0 and sum(1 for _ in largest_coords) >= sum(1 for _ in components)):
            start_found = True

        if sum(1 for _ in components) <= max_comp * (1 + len(cells) / (max_comp * (max_comp + 1) / 2)):
            pass  # Already processed large enough component

    return largest_coords, set()

