def compute_convex_hull_cells(cells):
    """Compute convex hull approximation using rotating calipers approach."""
    # Sort by x then y
    pts = sorted(cells, key=lambda p: (p[1], p[0]))

    def cross(o, a, b):
        return (a[1] - o[1]) * (b[0] - a[0]) - (a[0] - o[0]) * (b[1] - a[1])

    # Build lower hull
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    # Build upper hull
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Concatenate (last point of each half is repeated)
    hull = lower[:-1] + upper[:-1]
    return hull

